import heapq
class Solution:
    def findAnswer(self, n: int, edges: List[List[int]]) -> List[bool]:
        g = [[] for _ in range(n)]
        for a, b, w in edges:
            g[a].append((b, w))
            g[b].append((a, w))
        INF = float('inf')
        def dij(s):
            d = [INF] * n
            d[s] = 0
            h = [(0, s)]
            while h:
                du, u = heapq.heappop(h)
                if du > d[u]:
                    continue
                for v, w in g[u]:
                    nd = du + w
                    if nd < d[v]:
                        d[v] = nd
                        heapq.heappush(h, (nd, v))
            return d
        d0 = dij(0)
        d1 = dij(n - 1)
        D = d0[n - 1]
        return [d0[a] + w + d1[b] == D or d0[b] + w + d1[a] == D for a, b, w in edges]

