class Solution {
    public boolean[] findAnswer(int n, int[][] edges) {
        List<List<long[]>> g = new ArrayList<>();
        for (int i = 0; i < n; i++) g.add(new ArrayList<>());
        for (int[] e : edges) {
            g.get(e[0]).add(new long[]{e[1], e[2]});
            g.get(e[1]).add(new long[]{e[0], e[2]});
        }
        long[] d0 = dij(0, n, g), d1 = dij(n - 1, n, g);
        long D = d0[n - 1];
        boolean[] ans = new boolean[edges.length];
        for (int i = 0; i < edges.length; i++) {
            int a = edges[i][0], b = edges[i][1], w = edges[i][2];
            ans[i] = d0[a] + w + d1[b] == D || d0[b] + w + d1[a] == D;
        }
        return ans;
    }
    private long[] dij(int s, int n, List<List<long[]>> g) {
        long INF = Long.MAX_VALUE / 4;
        long[] d = new long[n];
        Arrays.fill(d, INF);
        d[s] = 0;
        PriorityQueue<long[]> pq = new PriorityQueue<>((x, y) -> Long.compare(x[0], y[0]));
        pq.add(new long[]{0, s});
        while (!pq.isEmpty()) {
            long[] top = pq.poll();
            int u = (int) top[1];
            if (top[0] > d[u]) continue;
            for (long[] vw : g.get(u)) {
                int v = (int) vw[0];
                if (top[0] + vw[1] < d[v]) {
                    d[v] = top[0] + vw[1];
                    pq.add(new long[]{d[v], v});
                }
            }
        }
        return d;
    }
}

