import heapq
from collections import deque
class Solution:
    def findAnswer(self, n: int, edges: List[List[int]]) -> List[bool]:
        g = [[] for _ in range(n)]
        for a, b, w in edges:
            g[a].append((b, w))
            g[b].append((a, w))
        INF = float('inf')
        d = [INF] * n
        d[0] = 0
        h = [(0, 0)]
        while h:
            du, u = heapq.heappop(h)
            if du > d[u]:
                continue
            for v, w in g[u]:
                if du + w < d[v]:
                    d[v] = du + w
                    heapq.heappush(h, (du + w, v))
        dag = [[] for _ in range(n)]
        rdag = [[] for _ in range(n)]
        for i, (a, b, w) in enumerate(edges):
            if d[a] + w == d[b]:
                dag[a].append((b, i)); rdag[b].append((a, i))
            if d[b] + w == d[a]:
                dag[b].append((a, i)); rdag[a].append((b, i))
        def bfs(gr, s):
            vis = [False] * n
            vis[s] = True
            q = deque([s])
            while q:
                u = q.popleft()
                for v, _ in gr[u]:
                    if not vis[v]:
                        vis[v] = True
                        q.append(v)
            return vis
        reach = bfs(dag, 0)
        coreach = bfs(rdag, n - 1)
        return [(d[a] + w == d[b] and reach[a] and coreach[b]) or
                (d[b] + w == d[a] and reach[b] and coreach[a]) for a, b, w in edges]

