class Solution {
    public boolean[] findAnswer(int n, int[][] edges) {
        List<List<long[]>> g = new ArrayList<>();
        for (int i = 0; i < n; i++) g.add(new ArrayList<>());
        for (int[] e : edges) {
            g.get(e[0]).add(new long[]{e[1], e[2]});
            g.get(e[1]).add(new long[]{e[0], e[2]});
        }
        long INF = Long.MAX_VALUE / 4;
        long[] d = new long[n];
        Arrays.fill(d, INF);
        d[0] = 0;
        PriorityQueue<long[]> pq = new PriorityQueue<>((x, y) -> Long.compare(x[0], y[0]));
        pq.add(new long[]{0, 0});
        while (!pq.isEmpty()) {
            long[] t = pq.poll();
            int u = (int) t[1];
            if (t[0] > d[u]) continue;
            for (long[] vw : g.get(u)) {
                int v = (int) vw[0];
                if (t[0] + vw[1] < d[v]) { d[v] = t[0] + vw[1]; pq.add(new long[]{d[v], v}); }
            }
        }
        List<List<int[]>> dag = new ArrayList<>(), rdag = new ArrayList<>();
        for (int i = 0; i < n; i++) { dag.add(new ArrayList<>()); rdag.add(new ArrayList<>()); }
        for (int i = 0; i < edges.length; i++) {
            int a = edges[i][0], b = edges[i][1], w = edges[i][2];
            if (d[a] < INF && d[a] + w == d[b]) { dag.get(a).add(new int[]{b, i}); rdag.get(b).add(new int[]{a, i}); }
            if (d[b] < INF && d[b] + w == d[a]) { dag.get(b).add(new int[]{a, i}); rdag.get(a).add(new int[]{b, i}); }
        }
        boolean[] reach = bfs(dag, 0, n), coreach = bfs(rdag, n - 1, n);
        boolean[] ans = new boolean[edges.length];
        for (int i = 0; i < edges.length; i++) {
            int a = edges[i][0], b = edges[i][1], w = edges[i][2];
            ans[i] = (d[a] < INF && d[a] + w == d[b] && reach[a] && coreach[b]) ||
                     (d[b] < INF && d[b] + w == d[a] && reach[b] && coreach[a]);
        }
        return ans;
    }
    private boolean[] bfs(List<List<int[]>> gr, int s, int n) {
        boolean[] vis = new boolean[n];
        vis[s] = true;
        Deque<Integer> q = new ArrayDeque<>();
        q.add(s);
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int[] vi : gr.get(u)) if (!vis[vi[0]]) { vis[vi[0]] = true; q.add(vi[0]); }
        }
        return vis;
    }
}

